{"document": {"category": "csaf_security_advisory", "csaf_version": "2.0", "distribution": {"text": "Disclosure is not limited. (TLPv2: TLP:CLEAR)", "tlp": {"label": "WHITE"}}, "lang": "en", "notes": [{"category": "summary", "text": "The products listed below contain a vulnerability that could allow an attacker to boot an operating system or UEFI application signed with that test key, bypassing UEFI Secure Boot protections even when Secure Boot is enabled.

Siemens has released new versions for the affected products and recommends to update to the latest versions.", "title": "Summary"}, {"category": "general", "text": "As a general security measure, Siemens strongly recommends to protect network access to devices with appropriate mechanisms. In order to operate the devices in a protected IT environment, Siemens recommends to configure the environment according to Siemens' operational guidelines for Industrial Security (Download: https://www.siemens.com/cert/operational-guidelines-industrial-security), and to follow the recommendations in the product manuals.
Additional information on Industrial Security by Siemens can be found at: https://www.siemens.com/industrialsecurity", "title": "General Recommendations"}, {"category": "general", "text": "For further inquiries on security vulnerabilities in Siemens products and solutions, please contact the Siemens ProductCERT: https://www.siemens.com/cert/advisories", "title": "Additional Resources"}, {"category": "legal_disclaimer", "text": "The use of Siemens Security Advisories is subject to the terms and conditions listed on: https://www.siemens.com/productcert/terms-of-use.", "title": "Terms of Use"}], "publisher": {"category": "vendor", "contact_details": "productcert@siemens.com", "name": "Siemens ProductCERT", "namespace": "https://www.siemens.com"}, "references": [{"category": "self", "summary": "SSA-159454: Hard-coded Key Vulnerability in SIMATIC IPCs - HTML Version", "url": "https://cert-portal.siemens.com/productcert/html/ssa-159454.html"}, {"category": "self", "summary": "SSA-159454: Hard-coded Key Vulnerability in SIMATIC IPCs - CSAF Version", "url": "https://cert-portal.siemens.com/productcert/csaf/ssa-159454.json"}], "title": "SSA-159454: Hard-coded Key Vulnerability in SIMATIC IPCs", "tracking": {"current_release_date": "2026-10-13T00:00:00.000Z", "generator": {"engine": {"name": "Siemens ProductCERT CSAF Generator", "version": "1"}}, "id": "SSA-159454", "initial_release_date": "2026-10-13T00:00:00.000Z", "revision_history": [{"date": "2026-10-13T00:00:00.000Z", "legacy_version": "1.0", "number": "1", "summary": "Publication Date"}], "status": "interim", "version": "1"}}, "product_tree": {"branches": [{"branches": [{"branches": [{"category": "product_version_range", "name": "vers:intdot/<31.01.13", "product": {"name": "SIMATIC IPC BX-21A < V31.01.13", "product_id": "1"}}], "category": "product_name", "name": "SIMATIC IPC BX-21A"}, {"branches": [{"category": "product_version_range", "name": "vers:intdot/<1.1.4", "product": {"name": "SIMATIC IPC RW-543A < V1.1.4", "product_id": "2"}}], "category": "product_name", "name": "SIMATIC IPC RW-543A"}, {"branches": [{"category": "product_version_range", "name": "vers:intdot/<28.01.15", "product": {"name": "SIMATIC IPC227G / IPC277G / IPC277G PRO / IPC327G / IPC377G < V28.01.15", "product_id": "3"}}], "category": "product_name", "name": "SIMATIC IPC227G / IPC277G / IPC277G PRO / IPC327G / IPC377G"}], "category": "vendor", "name": "Siemens"}]}, "vulnerabilities": [{"cve": "CVE-2026-72895", "cwe": {"id": "CWE-1394", "name": "Use of Default Cryptographic Key"}, "notes": [{"category": "description", "text": "A BIOS vendor test key is present in the UEFI Secure Boot key database. This could allow a local attacker with physical or administrative access to the device to boot an operating system or UEFI application signed with that test key, bypassing UEFI Secure Boot protections even when Secure Boot is enabled, potentially leading to a full loss of confidentiality, integrity, and availability of the device.", "title": "CVE Description"}], "product_status": {"known_affected": ["1", "2", "3"]}, "remediations": [{"category": "mitigation", "details": "<br/>Note:  After upgrading to the fixed BIOS version, users must load the BIOS default settings. If Secure Boot keys were already provisioned, they must be provisioned again afterwards.", "product_ids": ["1", "2"]}, {"category": "mitigation", "details": "<br/>Note: After upgrading to the fixed BIOS version, users must load the BIOS default settings. If Secure Boot keys were already provisioned, they must be provisioned again afterwards.", "product_ids": ["3"]}, {"category": "mitigation", "details": "As a temporary mitigation, users can manually remove the test key from the database (e.g., "DO NOT TRUST - AMI Test PK" for RW-543A or "insyde-ElkhartLake" for IPC227G/277G/327G/377G and BX-21A). Note: Loading default settings will restore the test key, so upgrading remains recommended.", "product_ids": ["1", "2", "3"]}, {"category": "vendor_fix", "details": "Update to V1.1.4 or later version", "product_ids": ["2"], "url": "https://support.industry.siemens.com/cs/ww/en/view/109763408/"}, {"category": "vendor_fix", "details": "Update to V28.01.15 or later version", "product_ids": ["3"], "url": "https://support.industry.siemens.com/cs/ww/en/view/109763408/"}, {"category": "vendor_fix", "details": "Update to V31.01.13 or later version", "product_ids": ["1"], "url": "https://support.industry.siemens.com/cs/ww/en/view/109763408/"}], "scores": [{"cvss_v3": {"baseScore": 7.7, "baseSeverity": "HIGH", "vectorString": "CVSS:3.1/AV:L/AC:H/PR:N/UI:R/S:C/C:H/I:H/A:H", "version": "3.1"}, "products": ["1", "2", "3"]}], "title": "CVE-2026-72895"}]}
